WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_eng_st_multi'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '多阶段衔接', 'kp-eng-st-multi', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "多阶段衔接"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "把工程切分为 3 个以上的碎片阶段。列出“全生命周期工作量方程”。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "又臭又长的流水账：“甲先做2天，然后甲乙合作3天，接着丙加入做了4天，最后甲丙合作直到完工”。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心法则"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "化繁为简，打破时间轴的壁垒，回归“人盯人”的总量守恒。"}]}, {"type": "katexBlock", "attrs": {"content": "W_{总} = P_A \\times \\sum T_A + P_B \\times \\sum T_B + P_C \\times \\sum T_C"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[赋出总量 W 和所有人的单体效率 P] --> B[不要按时间段去一段段算!]\nB --> C[拿出一张表, 统计 甲 总共出场了几天, 乙 总共出场了几天]\nC --> D[如果某阶段天数未知, 设为未知数 X]\nD --> E[列出一个终极总和方程: P甲*T甲总 + P乙*T乙总 = W]\nE --> F[解一元一次方程即得 X]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题推导模型"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "假设 W=60，Pa=3, Pb=2, Pc=1。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "题干：A先做2天；AB合作3天；ABC合作 X 天完工。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "盯 A：A 出场了 2 + 3 + X 天。A干的活 = 3 × (5+X)。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "盯 B：B 出场了 3 + X 天。B干的活 = 2 × (3+X)。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "盯 C：C 出场了 X 天。C干的活 = 1 × X。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "终极方程：3(5+X) + 2(3+X) + 1*X = 60。 15+3X + 6+2X + X = 60。 6X = 39。 X = 6.5。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "沉迷于分段减法：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "按阶段减（60 - 3*2 = 54；54 - 5*3 = 39；39 / 6 = 6.5）虽然能做出来，但在阶段多于3个、且中间穿插人员退出时，大脑极其容易遗漏。用代数方程把所有人从头到尾的总出勤汇总，是容错率最高的解法。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "对于极其复杂的工程题，养成写大方程的习惯。公考数学不怕列方程，就怕逻辑理不清。"}]}]}$$ AS jsonb), NULL, '多阶段衔接的核心考点与实战推导。', category_node.id, CAST('["数量关系", "工程问题", "多阶段衔接"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_eng_st_multi", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
